<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,computed} from 'vue'
import ProcessComparison from '@/components/ProcessComparison.vue'
import MaintenancePlans from '@/components/MaintenancePlans.vue'
import MainLayout from '@/components/MainLayout.vue'
import QueryTable from '@/components/QueryTable.vue'
import request from '@/utils/request'
import {useAuthStore} from '@/stores/auth'
type Row=Record<string,any>
const state=ref<Row>({rules:[],todos:[],events:[]}),suggestions=ref<Row[]>([]),error=ref(''),updated=ref(''),busy=ref(false),auth=useAuthStore()
const role=computed(()=>Number(auth.effectiveRoleId)),canRule=computed(()=>[1,2,9].includes(role.value)),canRun=computed(()=>[1,2,4,9].includes(role.value)),canConfirm=computed(()=>[6,9].includes(role.value))
let timer=0
async function load(){try{state.value=await request.get('/automation');if([1,2,6,9].includes(role.value))suggestions.value=await request.get('/automation/suggestions');updated.value=new Date().toLocaleTimeString();error.value=''}catch(e:any){error.value=e.message}}
async function act(path:string,body:Row={}){busy.value=true;try{await request.post(path,body);await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(()=>{load();timer=window.setInterval(()=>{if(document.visibilityState==='visible'&&!busy.value)load()},10000)});onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><MainLayout><div class="automation-page space-y-5"><div class="flex justify-between"><div><p class="text-sm text-blue-600">制造协同</p><h1 class="text-2xl font-bold mt-1">自动任务与提醒</h1><p class="text-sm text-slate-500 mt-2">完整报工 → 自动待办 → 人工检验 → 放行与进度更新。每10秒刷新；最近更新 {{updated||'等待加载'}}。</p></div><button @click="load" class="border rounded px-4">刷新</button></div><p v-if="error" class="bg-red-50 text-red-700 p-4 rounded" role="alert">{{error}}</p>
<section class="bg-blue-50 rounded-xl p-5 text-sm space-y-2"><p><strong>报工后质检：</strong>工序报工达到要求时自动生成质检待办，由质检员检测；系统不代替人工判定。</p><p><strong>库存补货：</strong>库存低于安全值时计算缺口，采购员确认后办理采购审批。</p><p><strong>周期保养：</strong>到提前提醒日期生成保养单，由设备维护员开始并填报结果。</p></section><details v-if="[8,9].includes(role)" class="bg-white border rounded-xl p-5"><summary class="font-semibold cursor-pointer">展开周期保养计划与任务</summary><MaintenancePlans/></details><div class="bg-white border rounded-xl p-5 flex justify-between items-center"><div><h2 class="font-semibold">{{state.rules[0]?.name}}</h2><p class="text-sm text-slate-500 mt-1">状态：{{state.rules[0]?.enabled?'已启用':'已停用'}}。同一工序只生成一个事件和待办，失败后可人工重试，最多执行三次。</p></div><button v-if="canRule" :disabled="busy" @click="act('/automation/rule',{enabled:!state.rules[0]?.enabled})" class="border rounded px-4 py-2">{{state.rules[0]?.enabled?'停用规则':'启用规则'}}</button></div>
<ProcessComparison v-if="[1,2,4,9].includes(role)"/><section class="bg-white border rounded-xl p-5 space-y-4"><h2 class="font-semibold text-lg">质检待办与生成来源</h2><p class="text-sm text-slate-500">后台自动记录的耗时取自事件与待办的真实时间差；人工创建记录单独标注，操作耗时见下方对比。检验不合格会保留待复检记录。</p><QueryTable :rows="state.todos"><template #default="{row}"><router-link v-if="[4,9].includes(role)&&row.status!=='DONE'" :to="`/manufacturing?workOrder=${row.work_order_id}&taskId=${row.task_id}`" class="text-blue-600 whitespace-nowrap">执行检验</router-link></template></QueryTable></section>
<section class="bg-white border rounded-xl p-5 space-y-4"><div class="flex justify-between"><h2 class="font-semibold text-lg">自动化执行日志</h2><button v-if="canRun" :disabled="busy" @click="act('/automation/process')" class="text-blue-600">立即处理队列</button></div><QueryTable :rows="state.events"><template #default="{row}"><button v-if="canRun&&['FAILED','SKIPPED'].includes(row.status)&&row.attempts<3" :disabled="busy" class="text-blue-600" @click="act('/automation/retry/'+row.id)">重试</button></template></QueryTable></section>
<section v-if="[1,2,6,9].includes(role)" class="bg-white border rounded-xl p-5 space-y-4"><h2 class="font-semibold text-lg">安全库存补货建议</h2><p class="text-sm text-slate-500">建议量 = 安全库存 − 当前库存，仅展示正缺口。采购员确认后仍需人工创建采购单，不自动采购。</p><QueryTable :rows="suggestions"><template #default="{row}"><button v-if="canConfirm&&row.status!=='CONFIRMED'" :disabled="busy" @click="act('/automation/suggestions/'+row.material_id+'/confirm')" class="text-blue-600">确认建议</button></template></QueryTable></section></div></MainLayout></template>

<style scoped>
.automation-page{color:#514a40}.automation-page>div:first-child{padding:24px 28px;border:1px solid #e1d6c5;border-radius:12px;background:linear-gradient(115deg,#f7f4ed,#efe8dc);align-items:center;gap:20px}.automation-page :deep(section){border-color:#e5dfd4;border-radius:12px;box-shadow:none}.automation-page :deep(.text-slate-500),.automation-page :deep(.text-slate-600){color:#888174}.automation-page :deep(.text-blue-600){color:#92734c}.automation-page :deep(.border){border-color:#e5dfd4}.automation-page>div:first-child>button{background:#fffdf9;color:#806642;border-color:#d8c8ad;padding:8px 18px;border-radius:7px;flex-shrink:0}.automation-page :deep(h2){color:#514a40}.automation-page :deep(button:focus-visible){outline:2px solid #92734c;outline-offset:3px}
@media(max-width:760px){.automation-page>div:first-child{padding:18px;align-items:flex-start;flex-wrap:wrap}}
.automation-page :deep(.bg-blue-50){background:#f3ede2!important;color:#806642!important;border-color:#e1d6c5!important}.automation-page :deep(.text-blue-700){color:#806642!important}</style>
